# ONE FILE — copy only this .ps1 to C:\Users\Administrator\Desktop\Erp\
# Business Central Administration Shell (Run as Administrator):
#   cd $env:USERPROFILE\Desktop\Erp
#   Set-ExecutionPolicy -Scope Process Bypass -Force
#   .\Install-ABH-BC-925.ps1

$ErrorActionPreference = "Stop"
$ErpFolder = "$env:USERPROFILE\Desktop\Erp"
$AppName = "BC24_TA App"
$Publisher = "Technology Associates EA Ltd"
$Version = "1.0.2.925"
$AppFileName = "Technology Associates EA Ltd_BC24_TA App_1.0.2.925.app"
$AppPath = Join-Path $ErpFolder $AppFileName

Set-Location $ErpFolder
Write-Host "Writing $AppFileName ..." -ForegroundColor Cyan
$b64 = @"

"@
[IO.File]::WriteAllBytes($AppPath, [Convert]::FromBase64String($b64))
Write-Host "Wrote $AppPath ($((Get-Item $AppPath).Length) bytes)"

Write-Host "Publishing $Version ..." -ForegroundColor Yellow
Publish-NAVApp -Path $AppPath -ServerInstance BC240 -SkipVerification

$pub = Get-NAVAppInfo -ServerInstance BC240 -Name $AppName -Publisher $Publisher |
    Where-Object { $_.Version -eq [version]$Version }
if (-not $pub -or -not $pub.IsPublished) {
    throw "Publish failed for $Version"
}
Write-Host "Published OK" -ForegroundColor Green

Sync-NAVApp -ServerInstance BC240 -Tenant default -Name $AppName -Publisher $Publisher -Version $Version
Start-NAVAppDataUpgrade -ServerInstance BC240 -Tenant default -Name $AppName -Publisher $Publisher -Version $Version

Get-NAVAppInfo -ServerInstance BC240 -Tenant default -TenantSpecificProperties -Name $AppName |
    Where-Object { $_.Version -eq [version]$Version } |
    Format-List Name, Version, IsPublished, IsInstalled
Write-Host "DONE — republish CuStaffPortal 50049 in Web Services" -ForegroundColor Green
